int EnforcementConfig_from_json(const char *json, EnforcementConfig *obj) {
    yyjson_doc *doc = yyjson_read(json, strlen(json), 0);
    if (!doc) return -1;
    yyjson_val *root = yyjson_doc_get_root(doc);

    yyjson_val *v_project_name = yyjson_obj_get(root, "project_name");
    if (v_project_name) strncpy(obj->project_name, yyjson_get_str(v_project_name), sizeof(obj->project_name)-1);
    yyjson_val *v_default_policy = yyjson_obj_get(root, "default_policy");
    if (v_default_policy) obj->default_policy = yyjson_get_uint(v_default_policy);
    yyjson_val *v_llm_similarity_min = yyjson_obj_get(root, "llm_similarity_min");
    if (v_llm_similarity_min) obj->llm_similarity_min = yyjson_get_uint(v_llm_similarity_min);
    yyjson_val *v_det_similarity_min = yyjson_obj_get(root, "det_similarity_min");
    if (v_det_similarity_min) obj->det_similarity_min = yyjson_get_uint(v_det_similarity_min);
    yyjson_val *v_tandem_drift_max = yyjson_obj_get(root, "tandem_drift_max");
    if (v_tandem_drift_max) obj->tandem_drift_max = yyjson_get_uint(v_tandem_drift_max);
    yyjson_val *v_naming_strict = yyjson_obj_get(root, "naming_strict");
    if (v_naming_strict) obj->naming_strict = yyjson_get_int(v_naming_strict);
    yyjson_val *v_coverage_strict = yyjson_obj_get(root, "coverage_strict");
    if (v_coverage_strict) obj->coverage_strict = yyjson_get_int(v_coverage_strict);
    yyjson_val *v_block_on_fatal = yyjson_obj_get(root, "block_on_fatal");
    if (v_block_on_fatal) obj->block_on_fatal = yyjson_get_int(v_block_on_fatal);
    yyjson_val *v_output_format = yyjson_obj_get(root, "output_format");
    if (v_output_format) obj->output_format = yyjson_get_uint(v_output_format);

    yyjson_doc_free(doc);
    return 0;
}

